import{_ as t,o as i,c as n,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Classification et Caractéristiques de l'Énergie Anomale","description":"","frontmatter":{},"headers":[],"relativePath":"fr/55-奇异能量分类与特性.md","filePath":"fr/55-奇异能量分类与特性.md","lastUpdated":null}`),s={name:"fr/55-奇异能量分类与特性.md"};function a(l,e,o,d,u,c){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="classification-et-caracteristiques-de-l-energie-anomale" tabindex="-1">Classification et Caractéristiques de l&#39;Énergie Anomale <a class="header-anchor" href="#classification-et-caracteristiques-de-l-energie-anomale" aria-label="Permalink to &quot;Classification et Caractéristiques de l&#39;Énergie Anomale&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>55</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Énergie anomale, système de classification, caractéristiques énergétiques, évaluation des risques, contrôle énergétique</td></tr></tbody></table><h2 id="i-definition-et-portee-de-l-energie-anomale" tabindex="-1">I. Définition et Portée de l&#39;Énergie Anomale <a class="header-anchor" href="#i-definition-et-portee-de-l-energie-anomale" aria-label="Permalink to &quot;I. Définition et Portée de l&#39;Énergie Anomale&quot;">​</a></h2><p>Dans l&#39;Univers Originel Wanling Hengmao (Univers Hengyuan), l&#39;« énergie anomale » désigne les formes d&#39;énergie qui n&#39;appartiennent pas aux types d&#39;énergie conventionnels couverts par les Trois Cents Systèmes de Culture Originels connus, et qui possèdent des caractéristiques anomales ou des origines inconnues. La différence entre l&#39;énergie anomale et la vie anomale est : la vie anomale est une existence ayant des caractéristiques de vie, tandis que l&#39;énergie anomale est une forme d&#39;énergie qui ne possède pas de caractéristiques de vie complètes mais peut avoir une activité anomale.</p><p>Les sources de l&#39;énergie anomale incluent sans s&#39;y limiter : l&#39;énergie d&#39;univers étrangers fuyant des fissures interplans, l&#39;énergie préhistorique scellée dans des ruines anciennes, l&#39;énergie variante produite par des expériences à haute énergie, l&#39;énergie inconnue naturellement formée dans les profondeurs de l&#39;univers, et l&#39;énergie spéciale condensée à partir de fragments de lois. La nature inconnue et le danger potentiel de l&#39;énergie anomale en font une cible clé de la gouvernance énergétique de la Civilisation Symbiotique de l&#39;Ancre.</p><h2 id="ii-systeme-de-classification-de-l-energie-anomale" tabindex="-1">II. Système de Classification de l&#39;Énergie Anomale <a class="header-anchor" href="#ii-systeme-de-classification-de-l-energie-anomale" aria-label="Permalink to &quot;II. Système de Classification de l&#39;Énergie Anomale&quot;">​</a></h2><p>Selon ses caractéristiques essentielles et ses modèles comportementaux, l&#39;énergie anomale est divisée en cinq grandes catégories, chacune étant ensuite subdivisée en types spécifiques :</p><h3 id="i-classification-par-essence-energetique" tabindex="-1">(I) Classification par essence énergétique <a class="header-anchor" href="#i-classification-par-essence-energetique" aria-label="Permalink to &quot;(I) Classification par essence énergétique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Catégorie</th><th>Nom</th><th>Caractéristiques essentielles</th><th>Types représentatifs</th></tr></thead><tbody><tr><td>Première catégorie</td><td>Type de variation élémentaire</td><td>Variée à partir d&#39;énergies élémentaires connues, conservant certaines caractéristiques élémentaires mais avec des manifestations anomales</td><td>Feu Sombre, Eau des Enfers, Vent Céleste, Foudre Violette</td></tr><tr><td>Deuxième catégorie</td><td>Type dérivé des lois</td><td>Directement condensée à partir de fragments de lois cosmiques, possédant une puissance de niveau loi</td><td>Énergie Temporelle, Énergie Spatiale, Énergie Causale, Énergie du Destin</td></tr><tr><td>Troisième catégorie</td><td>Type de projection consciente</td><td>Énergie formée par la projection d&#39;une conscience puissante ou d&#39;une pensée collective, possédant des attributs conscients</td><td>Télékinésie, Pouvoir de la Foi, Pouvoir du Vœu, Pouvoir de Malédiction</td></tr><tr><td>Quatrième catégorie</td><td>Type d&#39;intrusion hétérogène</td><td>Énergie hétérogène provenant d&#39;autres univers ou plans, ne suivant pas les lois conventionnelles de cet univers</td><td>Énergie du Vide, Énergie du Chaos, Énergie des Abysses, Énergie de Lumière Sacrée</td></tr><tr><td>Cinquième catégorie</td><td>Type de variation mixte</td><td>Nouvelle énergie produite par la variation mixte de deux types d&#39;énergie ou plus, aux caractéristiques complexes et changeantes</td><td>Foudre de Feu du Chaos, Énergie des Fissures Spatio-temporelles, Énergie Mixte Vie-Mort</td></tr></tbody></table><h3 id="ii-classification-par-modele-comportemental-energetique" tabindex="-1">(II) Classification par modèle comportemental énergétique <a class="header-anchor" href="#ii-classification-par-modele-comportemental-energetique" aria-label="Permalink to &quot;(II) Classification par modèle comportemental énergétique&quot;">​</a></h3><ul><li><strong>Type stable</strong> : énergie aux propriétés stables, ne se modifiant ni ne se diffusant spontanément, relativement facile à contrôler.</li><li><strong>Type actif</strong> : énergie aux propriétés actives, fluctuant ou se diffusant spontanément, nécessitant une surveillance continue.</li><li><strong>Type érosif</strong> : possédant la caractéristique d&#39;éroder d&#39;autres énergies ou matières, assimilant continuellement l&#39;environnement environnant.</li><li><strong>Type dévorant</strong> : possédant la caractéristique de dévorer d&#39;autres énergies pour se renforcer, avec un risque de croissance incontrôlée.</li><li><strong>Type infectieux</strong> : possédant l&#39;infectiosité, capable d&#39;infecter d&#39;autres énergies ou formes de vie et de les convertir en énergie du même type.</li><li><strong>Type autodestructeur</strong> : énergie instable, avec un risque d&#39;explosion ou d&#39;annihilation spontanée.</li><li><strong>Type intelligent</strong> : énergie possédant une conscience ou une intelligence préliminaire, capable d&#39;actions et de décisions autonomes.</li></ul><h3 id="iii-classification-par-niveau-de-risque-energetique" tabindex="-1">(III) Classification par niveau de risque énergétique <a class="header-anchor" href="#iii-classification-par-niveau-de-risque-energetique" aria-label="Permalink to &quot;(III) Classification par niveau de risque énergétique&quot;">​</a></h3><p>En référence au système d&#39;évaluation des risques de la vie anomale, l&#39;énergie anomale est également divisée en quatre niveaux de risque :</p><table tabindex="0"><thead><tr><th>Niveau de risque</th><th>Nom</th><th>Critères</th><th>Direction de traitement</th></tr></thead><tbody><tr><td>Premier niveau</td><td>Risque faible</td><td>Propriétés stables, absence d&#39;érosivité, utilisable, impact environnemental contrôlable</td><td>Traitement de développement et d&#39;utilisation</td></tr><tr><td>Deuxième niveau</td><td>Risque moyen</td><td>Propriétés relativement actives, une certaine érosivité ou diffusivité, nécessite contrôle</td><td>Traitement de scellement et de surveillance</td></tr><tr><td>Troisième niveau</td><td>Risque élevé</td><td>Forte érosivité/dévoration/infectiosité, incontrôlable, dommages environnementaux graves</td><td>Traitement de purification et de dissolution</td></tr><tr><td>Quatrième niveau</td><td>Risque extrêmement élevé</td><td>Possède un pouvoir destructeur de niveau cosmique, menace de niveau loi, incontrôlable, menace la survie de la civilisation</td><td>Dissolution d&#39;urgence + rapport</td></tr></tbody></table><h2 id="iii-explication-detaillee-des-principaux-types-d-energie-anomale" tabindex="-1">III. Explication Détaillée des Principaux Types d&#39;Énergie Anomale <a class="header-anchor" href="#iii-explication-detaillee-des-principaux-types-d-energie-anomale" aria-label="Permalink to &quot;III. Explication Détaillée des Principaux Types d&#39;Énergie Anomale&quot;">​</a></h2><h3 id="i-type-de-variation-elementaire" tabindex="-1">(I) Type de variation élémentaire <a class="header-anchor" href="#i-type-de-variation-elementaire" aria-label="Permalink to &quot;(I) Type de variation élémentaire&quot;">​</a></h3><ul><li><strong>Feu Sombre</strong> : varié à partir d&#39;éléments de feu, de couleur noire sombre, température extrêmement élevée mais non lumineux, possédant la caractéristique de dévorer la lumière. Le Feu Sombre peut brûler des substances que les flammes conventionnelles ne peuvent brûler, y compris l&#39;énergie et l&#39;espace.</li><li><strong>Eau des Enfers</strong> : variée à partir d&#39;éléments d&#39;eau, de couleur vert sombre, possédant des attributs corrosifs et de mort, capable d&#39;éroder la vitalité des formes de vie. L&#39;Eau des Enfers est couramment utilisée dans les sorts nécromantiques et la culture corrosive.</li><li><strong>Vent Céleste</strong> : varié à partir d&#39;éléments de vent, extrêmement fort avec des attributs de coupure, capable de couper la matière et l&#39;énergie. Le Vent Céleste provient principalement des hautes altitudes et près des fissures spatiales.</li><li><strong>Foudre Violette</strong> : variée à partir d&#39;éléments de foudre, de couleur violette, avec une puissance dépassant de loin la foudre conventionnelle, possédant la caractéristique de perturber les lois. La Foudre Violette est une ressource de culture convoitée par les cultivateurs avancés, mais le risque de l&#39;obtenir est extrêmement élevé.</li></ul><h3 id="ii-type-derive-des-lois" tabindex="-1">(II) Type dérivé des lois <a class="header-anchor" href="#ii-type-derive-des-lois" aria-label="Permalink to &quot;(II) Type dérivé des lois&quot;">​</a></h3><ul><li><strong>Énergie Temporelle</strong> : condensée à partir de fragments de la loi du temps, capable d&#39;accélérer ou de ralentir le flux temporel local, ou même d&#39;effectuer des sauts temporels à courte distance. L&#39;Énergie Temporelle est extrêmement rare et instable ; une utilisation inappropriée peut causer des paradoxes temporels.</li><li><strong>Énergie Spatiale</strong> : condensée à partir de fragments de la loi de l&#39;espace, capable d&#39;effectuer des opérations de pliage spatial, de téléportation spatiale et de coupe spatiale. L&#39;Énergie Spatiale est la ressource centrale du système de régulation des principes juridiques spatiaux.</li><li><strong>Énergie Causale</strong> : condensée à partir de fragments de la loi de causalité, capable d&#39;intervenir dans les chaînes causales et de modifier les relations de cause à effet des événements. L&#39;utilisation de l&#39;Énergie Causale est strictement limitée pour prévenir le désordre causal.</li><li><strong>Énergie du Destin</strong> : condensée à partir de fragments de la loi du destin, capable d&#39;influencer les trajectoires de destin des formes de vie et de modifier la fortune et la chance. L&#39;utilisation de l&#39;Énergie du Destin implique de profondes questions éthiques et est soumise au contrôle le plus strict.</li></ul><h3 id="iii-type-de-projection-consciente" tabindex="-1">(III) Type de projection consciente <a class="header-anchor" href="#iii-type-de-projection-consciente" aria-label="Permalink to &quot;(III) Type de projection consciente&quot;">​</a></h3><ul><li><strong>Télékinésie</strong> : énergie formée par la projection d&#39;une pensée puissante, capable de manipuler directement la matière et l&#39;énergie avec l&#39;esprit. La Télékinésie est la capacité innée de la Niàn Zú (Race d&#39;Esprit) ; d&#39;autres races peuvent aussi la maîtriser par la culture.</li><li><strong>Pouvoir de la Foi</strong> : énergie condensée à partir de la foi et du culte d&#39;un grand nombre de croyants, possédant des attributs sacrés et des capacités de guérison. Le Pouvoir de la Foi est la ressource centrale des systèmes de culture divine, mais une dépendance excessive au Pouvoir de la Foi peut provoquer l&#39;assimilation de la conscience par les croyants.</li><li><strong>Pouvoir du Vœu</strong> : énergie condensée à partir des beaux souhaits de tous les êtres, possédant des attributs créatifs et bénissants. Le Pouvoir du Vœu est l&#39;une des sources d&#39;énergie importantes de la Civilisation Symbiotique de l&#39;Ancre ; la diffusion du concept symbiotique peut accumuler le Pouvoir du Vœu.</li><li><strong>Pouvoir de Malédiction</strong> : énergie condensée à partir d&#39;un ressentiment intense et de la malveillance, possédant des attributs destructeurs et maudissants. Le Pouvoir de Malédiction est une énergie négative dangereuse ; une utilisation inappropriée se retournera contre l&#39;utilisateur et est soumise à un contrôle strict.</li></ul><h3 id="iv-type-d-intrusion-heterogene" tabindex="-1">(IV) Type d&#39;intrusion hétérogène <a class="header-anchor" href="#iv-type-d-intrusion-heterogene" aria-label="Permalink to &quot;(IV) Type d&#39;intrusion hétérogène&quot;">​</a></h3><ul><li><strong>Énergie du Vide</strong> : énergie hétérogène provenant du vide de l&#39;univers, possédant les caractéristiques du néant et de l&#39;annihilation, capable de dissoudre la matière et l&#39;énergie. L&#39;Énergie du Vide est une énergie dangereuse de niveau cosmique et doit être recherchée et utilisée dans des conditions strictement isolées.</li><li><strong>Énergie du Chaos</strong> : énergie primordiale provenant de l&#39;état chaotique antérieur à la naissance de l&#39;univers, possédant des possibilités infinies et l&#39;incontrôlabilité. L&#39;Énergie du Chaos peut être transformée en tout type d&#39;énergie, mais le processus de transformation est extrêmement dangereux.</li><li><strong>Énergie des Abysses</strong> : énergie sombre provenant des abysses de l&#39;univers, possédant des caractéristiques corrosives et corruptrices, capable d&#39;éroder la conscience et le corps des formes de vie. L&#39;Énergie des Abysses est étroitement liée à l&#39;origine des Entités de Remplacement Sombres (voir <em>57-黑暗置换体起源与本质</em>).</li><li><strong>Énergie de Lumière Sacrée</strong> : énergie sacrée provenant de plans supérieurs, possédant des caractéristiques purifiantes et curatives, capable de purifier l&#39;énergie sombre et de guérir les blessures graves. L&#39;Énergie de Lumière Sacrée est une arme efficace contre l&#39;Énergie des Abysses, mais une utilisation excessive peut provoquer une perte de contrôle de l&#39;ascension de la vie.</li></ul><h2 id="iv-analyse-des-caracteristiques-de-l-energie-anomale" tabindex="-1">IV. Analyse des Caractéristiques de l&#39;Énergie Anomale <a class="header-anchor" href="#iv-analyse-des-caracteristiques-de-l-energie-anomale" aria-label="Permalink to &quot;IV. Analyse des Caractéristiques de l&#39;Énergie Anomale&quot;">​</a></h2><p>Comparée à l&#39;énergie conventionnelle, l&#39;énergie anomale possède les caractéristiques communes suivantes :</p><table tabindex="0"><thead><tr><th>Caractéristique</th><th>Description</th></tr></thead><tbody><tr><td>Imprévisibilité</td><td>Les modèles comportementaux de l&#39;énergie anomale ne suivent souvent pas les lois énergétiques conventionnelles, difficiles à prédire précisément</td></tr><tr><td>Haute activité</td><td>L&#39;énergie anomale possède généralement une haute activité, réagissant facilement avec d&#39;autres énergies ou matières</td></tr><tr><td>Exclusivité</td><td>Certaines énergies anomales possèdent l&#39;exclusivité, repoussant ou dissolvant d&#39;autres types d&#39;énergie</td></tr><tr><td>Infectiosité</td><td>Certaines énergies anomales possèdent l&#39;infectiosité, capables d&#39;infecter ou de convertir d&#39;autres énergies et formes de vie</td></tr><tr><td>Évolutivité</td><td>L&#39;énergie anomale peut évoluer ou varier au fil du temps, produisant de nouvelles caractéristiques</td></tr><tr><td>Haute valeur</td><td>L&#39;énergie anomale possède souvent une puissance et des usages incomparables à l&#39;énergie conventionnelle, avec une valeur de recherche et d&#39;utilisation extrêmement élevée</td></tr><tr><td>Haut risque</td><td>La nature inconnue et les caractéristiques anomales de l&#39;énergie anomale la rendent hautement risquée ; un contrôle inapproprié peut causer des conséquences graves</td></tr></tbody></table><h2 id="v-detection-et-surveillance-de-l-energie-anomale" tabindex="-1">V. Détection et Surveillance de l&#39;Énergie Anomale <a class="header-anchor" href="#v-detection-et-surveillance-de-l-energie-anomale" aria-label="Permalink to &quot;V. Détection et Surveillance de l&#39;Énergie Anomale&quot;">​</a></h2><p>Pour découvrir et contrôler rapidement l&#39;énergie anomale, l&#39;État établit un système de détection et de surveillance de l&#39;énergie anomale :</p><ul><li><strong>Réseau de surveillance énergétique</strong> : établir des stations de surveillance énergétique dans tout l&#39;univers, surveillant en temps réel les fluctuations énergétiques des diverses régions et découvrant rapidement les signaux énergétiques anomaux.</li><li><strong>Surveillance des fissures interplans</strong> : effectuer une surveillance ciblée des fissures interplans pour empêcher l&#39;énergie hétérogène d&#39;envahir à travers les fissures.</li><li><strong>Surveillance énergétique des ruines</strong> : effectuer une surveillance énergétique des ruines anciennes et des sites archéologiques pour empêcher la fuite d&#39;énergie anomale scellée.</li><li><strong>Surveillance énergétique des expériences</strong> : effectuer une surveillance énergétique des expériences à haute énergie et des percées de culture pour empêcher l&#39;énergie anomale accidentellement produite de perdre le contrôle.</li><li><strong>Système d&#39;alerte énergétique</strong> : établir un système d&#39;alerte de l&#39;énergie anomale, publiant différents niveaux d&#39;information d&#39;alerte selon le niveau de risque de l&#39;énergie.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;énergie anomale est l&#39;une des existences les plus dignes de recherche et les plus dangereuses de l&#39;Univers Hengyuan. En établissant un système de classification systématique, en étudiant en profondeur les caractéristiques des divers types d&#39;énergie anomale et en établissant des réseaux de détection et de surveillance, la Civilisation Symbiotique de l&#39;Ancre pose une base scientifique pour le contrôle sûr et l&#39;utilisation rationnelle de l&#39;énergie anomale. Dans <em>56-奇异能量三类处置流程</em>, les plans de traitement normalisés pour l&#39;énergie anomale à différents niveaux de risque seront détaillés.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>56-奇异能量三类处置流程 (Processus de Traitement des Trois Types d&#39;Énergie Anomale)</li><li>15-能量循环与转化法则 (Lois de Circulation et de Transformation de l&#39;Énergie)</li><li>53-奇特生命识别标准 (Normes d&#39;Identification de la Vie Anomale)</li><li>57-黑暗置换体起源与本质 (Origine et Essence des Entités de Remplacement Sombres)</li></ul>',33)])])}const g=t(s,[["render",a]]);export{m as __pageData,g as default};
